param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld')
# Read-only index of prior evidence plus six targeted seed/selection types.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$base=Join-Path $root 'docs/research/rimworld/evidence'
function Digest([string]$file){(Get-FileHash -LiteralPath $file).Hash.ToLowerInvariant()}
function Source([string]$group,[string]$type,[int]$start,[int]$end){
 $manifest=Get-Content (Join-Path $base "$group-manifest.json") -Raw|ConvertFrom-Json
 $entry=@($manifest.types|Where-Object type -eq $type);if($entry.Count -ne 1){throw "Unknown type $group/$type"}
 if($start -lt 1 -or $end -lt $start -or $end -gt $entry[0].lines){throw 'Invalid source range'}
 if((Digest (Join-Path $root $entry[0].local_file)) -ne $entry[0].sha256){throw 'Derived source changed'}
 [ordered]@{group=$group;type=$type;file=$entry[0].local_file;sha256=$entry[0].sha256;lines=@($start,$end)}
}
function Prior([string]$group,[string[]]$ids){[ordered]@{file="$group-claims.json";ids=$ids}}
$claims=@(
 [ordered]@{id='WS01';kind='static-derived';finding='World generation and WorldInfo.Seed both use GenText.StableStringHash(seedString): null=>0, otherwise signed32 accumulation starting23, each UTF16 code unit multiplies by31 then adds the code unit. World seed text is stored separately from its derived integer.';sources=@((Source 'world-site-selection' 'Verse.GenText' 276 289),(Source 'world-site-selection' 'RimWorld.Planet.WorldInfo' 11 43),(Source 'generation' 'RimWorld.Planet.WorldGenerator' 176 179));prior=@((Prior 'generation' @('GN01')))},
 [ordered]@{id='WS02';kind='static-derived';finding='PlanetTile is tileId plus layer identity. Its hash is signed32(tileId*397) XOR effectiveLayer, with effectiveLayer0 when layerId<0 or Layer.IsRootSurface, otherwise layerId. Tile ID alone is not the ordinary local-map hash input; root-surface aliases normalize. This finite hash is not a collision-free world identity.';sources=@((Source 'world-site-selection' 'RimWorld.Planet.PlanetTile' 6 78));prior=@()},
 [ordered]@{id='WS03';kind='static-derived';finding='Ordinary GenerateMap derives HashCombineInt(world.info.Seed,parent.Tile.GetHashCode()); missing parent falls back0. Pocket-map path uses parent.ID or Rand.Int instead. HashCombineInt combines seed with value+2654435769+(seed<<6)+(seed>>2), then XOR and signed32 cast. Generation steps sort order,index and derive per-step seeds; this is not full map equivalence across versions, Defs, size or parameters.';sources=@((Source 'world-site-selection' 'Verse.Gen' 198 201),(Source 'generation' 'Verse.MapGenerator' 79 101),(Source 'generation' 'Verse.MapGenerator' 289 332),(Source 'generation' 'Verse.MapGenerator' 439 451));prior=@((Prior 'generation' @('GN07')))},
 [ordered]@{id='WS04';kind='static-derived-reuse';finding='World elevation, temperature, rainfall and hilliness are assigned before biome scoring. Rain and temperature are separate fields; hilliness is not solely an elevation bucket. Candidate biome requires implemented, generatesNaturally and layer permission; strict greater-than retains the earlier definition on ties. Prior27 covers four workers, not every competing biome.';sources=@((Source 'generation' 'RimWorld.Planet.WorldGenStep_Terrain' 215 323));prior=@((Prior 'generation' @('GN03','GN04')),(Prior 'biomes' @('BM01','BM02','BM13')))},
 [ordered]@{id='WS05';kind='static-derived-and-xml';finding='New-game CanDoNext checks selectedTile.Valid and TileFinder.IsValidTileForNewSettlement, then tutorial permission; DoNext invokes a proximity confirmation helper. Settlement validator rejects canBuildBase=false, unimplemented biomes and Impassable hilliness, then checks existing/adjacent settlements and other map/site occupancy. Viewing a tile does not prove settlement eligibility. Core Ocean/Lake explicitly cannotBuildBase.';sources=@((Source 'world-site-selection' 'RimWorld.Page_SelectStartingSite' 147 158),(Source 'world-site-selection' 'RimWorld.Page_SelectStartingSite' 182 221),(Source 'world-site-selection' 'RimWorld.Planet.TileFinder' 65 144));prior=@();xml=@('WSX01')},
 [ordered]@{id='WS06';kind='static-derived-reuse';finding='Region conditions affect local map settings: hilliness changes the elevation generator and mineable scatter base rate; biome changes terrain/plants and can force rock types. NaturalRockTypesIn otherwise seeds its temporary RNG from tile hash and samples2..3 eligible natural rocks. This does not establish all local terrain/ore layouts or guarantee exact resource amounts.';sources=@((Source 'generation' 'RimWorld.Planet.World' 391 429),(Source 'generation' 'RimWorld.GenStep_ElevationFertility' 57 81));prior=@((Prior 'generation' @('GN09','GN10','GN16')),(Prior 'biomes' @('BM03','BM04','BM07')))},
 [ordered]@{id='WS07';kind='prior-native-observation';finding='Prior28 clicked five existing-world land tiles and read Terrain/Planet UI: Desert, Temperate forest and Boreal forest; Flat, Mountainous and Impassable. Seed whip and coverage50% agree with saved metadata. It did not create a world, confirm a starting settlement or generate a local map, and did not prove same-seed equivalence. No native process is launched for this v35 index.';sources=@();prior=@();runtime='native-biomes-runtime.json'},
 [ordered]@{id='WS08';kind='static-derived-reuse';finding='World average climate and displayed growing season describe site tradeoffs, not guaranteed daily or room temperature and harvests. Prior climate/growth derivation distinguishes seasonal means, local temperature and biological plant limits. The five prior UI samples are observations, not a threshold fit.';sources=@();prior=@((Prior 'biomes' @('BM13','BM15','BM16','BM17','BM18')));runtime='native-biomes-runtime.json'},
 [ordered]@{id='WS09';kind='project-adaptation';finding='Web v35 uses a48x24 equirectangular regional map sampled on a sphere, three supported biomes, ocean/impassable settlement rejection and independently derived local-map seeds for existing64x64x16 maps. Rule version plus worldSeed plus region ID is persistent provenance. Region parameters are authored provisional choices, not the original globe, all-biome scoring or RNG. No rivers, local ocean simulation, travel or multiple maps is asserted.';sources=@();prior=@();adaptation='web_scope'}
)
$deps=@(
 'docs/research/rimworld/06-world-generation-resources.md','docs/research/rimworld/27-biomes-terrain-generation.md','docs/research/rimworld/28-native-world-generation-runtime.md',
 'docs/research/rimworld/evidence/generation-manifest.json','docs/research/rimworld/evidence/generation-claims.json','docs/research/rimworld/evidence/generation-xml.json',
 'docs/research/rimworld/evidence/biomes-manifest.json','docs/research/rimworld/evidence/biomes-claims.json','docs/research/rimworld/evidence/biomes-xml.json','docs/research/rimworld/evidence/biomes-cases.json',
 'docs/research/rimworld/evidence/environment-manifest.json','docs/research/rimworld/evidence/native-biomes-runtime.json','docs/research/rimworld/evidence/native-biomes-actions.jsonl',
 'scripts/research/verify-biomes-evidence.mjs','scripts/research/verify-biomes-runtime.mjs','scripts/research/read-biomes-runtime-save.ps1'
)
$dependencies=@(foreach($path in $deps){[ordered]@{file=$path;sha256=(Digest (Join-Path $root $path))}})
$waterFile='Data/Core/Defs/BiomeDefs/Biomes_Water.xml';$waterPath=Join-Path $GameRoot $waterFile
$doc=[xml](Get-Content -LiteralPath $waterPath -Raw);$xpath='/Defs/BiomeDef[defName="Ocean" or defName="Lake"]'
$xmlNodes=@(foreach($n in $doc.SelectNodes($xpath)){$copy=$n.CloneNode($false);foreach($child in $n.ChildNodes){if($child.LocalName -in @('defName','workerClass','isWaterBiome','canBuildBase','impassable','implemented')){[void]$copy.AppendChild($child.CloneNode($true))}};$copy.OuterXml})
$m=Get-Content (Join-Path $base 'world-site-selection-manifest.json') -Raw|ConvertFrom-Json
$e=[ordered]@{
 schema_version=1;evidence_id='RW17-WORLD-SITE-SELECTION';date_local='2026-11-04';version_text=$m.version_text;source_sha256=$m.source_sha256
 kind='Targeted static seed/settlement audit and index of unchanged prior world/biome/native evidence'
 manifests=@('world-site-selection','generation','biomes');dependencies=$dependencies;claims=$claims
 xml=@([ordered]@{id='WSX01';file=$waterFile;source_sha256=(Digest $waterPath);xpath=$xpath;projection='Original attributes and selected gameplay fields; Ocean/Lake have no ParentName';nodes=$xmlNodes})
 arithmetic_cases=@(
  [ordered]@{id='WSH01';seed_string='whip';tile_id=99363;layer_id=0;root_surface=$true;world_seed=24889423;tile_hash=39447111;map_seed=-23486052},
  [ordered]@{id='WSH02';seed_string='whip';tile_id=111646;layer_id=0;root_surface=$true;world_seed=24889423;tile_hash=44323462;map_seed=22485597},
  [ordered]@{id='WSH03';seed_string='whip';tile_id=99363;layer_id=2;root_surface=$false;world_seed=24889423;tile_hash=39447109;map_seed=-23486050},
  [ordered]@{id='WSH04';seed_string='whip';tile_id=99363;layer_id=-1;root_surface=$false;world_seed=24889423;tile_hash=39447111;map_seed=-23486052},
  [ordered]@{id='WSH05';seed_string='迁徙🌲';tile_id=282619;layer_id=0;root_surface=$true;world_seed=1142871301;tile_hash=112199743;map_seed=-105206404}
 )
 arithmetic_scope='Independent signed32/UTF16 formula evaluation only; not executed game methods, decoded map seeds, terrain generation or native replay'
 runtime_reuse=[ordered]@{file='native-biomes-runtime.json';chapter='28-native-world-generation-runtime.md';tile_ids=@(282619,99363,111646,118124,176455);new_native_run=$false;new_world_generation=$false;starting_site_confirmation=$false;local_map_generated=$false;same_seed_equivalence=$false;prior_unintended_advanced_ticks=83122}
 web_scope=[ordered]@{region_dimensions=@(48,24);local_dimensions=@(64,64,16);supported_biomes=@('temperate','boreal','desert');view='sphere-sampled equirectangular regional projection';identity_fields=@('version','worldSeed','tileId');rule_version=1;parameters='provisional project design; lock version1 resolution for old saves';excluded=@('original spherical tessellation','all original biome workers','original RNG equivalence','rivers','local ocean simulation','travel','multiple maps')}
 limitations=@('Prior27 reviewed four biome workers; the full candidate set and all scoring functions remain outside this audit.','Prior28 is an existing-world inspection with a recorded unintended simulation advance, not a new starting-site or generation trial.','No newly captured runtime images or native run in v35. Existing eight crops/five saves are verified in place.','Only normal settlement gates are traced; proximity helper details, full occupancy helper and gravship exceptions are not fully reconstructed.','Same numeric seed does not prove identical maps under changed version, effective Defs, generator, map size, settings or random sequence.','32-bit hash outputs may collide. Preserve full region identity and rules version independently from local seed.','Full derived C# remains local. No game assembly is loaded for execution.')
}
[IO.File]::WriteAllText((Join-Path $base 'world-site-selection-evidence.json'),($e|ConvertTo-Json -Depth 18).Replace("`r`n","`n")+"`n",[Text.UTF8Encoding]::new($false))
"$($claims.Count) indexed claims; $($dependencies.Count) reused artifacts; $($m.types.Count) targeted types."
